// GENERATED BY THE PROJECT INTEGRATION COORDINATOR — do not edit.
// Every page any feature contributed is routed here AND linked in the nav. The two lists are one
// list, so a page cannot be built and left unreachable — which is what happened to three of
// DemoFR's four pages.
//
// basename={mountBase()} is NOT decoration. Without it this shell renders the nav and an EMPTY PAGE
// whenever it is served from a sub-path, which is how every preview is served. Measured on #9.
import { BrowserRouter, NavLink, Route, Routes } from "react-router-dom";
import { UserAccountsProfilesPage } from "./views/UserAccountsProfilesPage";

/**
 * Where this app is mounted. "/" in your own deployment; a preview serves it from a sub-path and
 * says so in a meta tag. Without this the router matches none of its routes under that sub-path and
 * renders an empty page.
 */
function mountBase(): string {
  if (typeof document === "undefined") return "/";
  const raw = document.querySelector('meta[name="orchstate-app-base"]')?.getAttribute("content") ?? "";
  const v = raw.trim();
  if (!v.startsWith("/") || v.startsWith("//")) return "/";
  return v.replace(/\/+$/, "") || "/";
}

const linkClass = ({ isActive }: { isActive: boolean }) =>
  isActive ? "px-3 py-2 font-semibold underline" : "px-3 py-2";

export default function App() {
  return (
    <BrowserRouter basename={mountBase()}>
      <nav className="flex gap-2 border-b p-3">
        <NavLink to="/user-accounts-profiles" className={linkClass}>User Accounts Profiles</NavLink>
      </nav>
      <main className="p-4">
        <Routes>
          <Route path="/" element={<UserAccountsProfilesPage />} />
          <Route path="/user-accounts-profiles" element={<UserAccountsProfilesPage />} />
        </Routes>
      </main>
    </BrowserRouter>
  );
}
